/* ============================================
   GreenBean Coffee — Design System
   ============================================ */

/* --- Primitive Tokens (OKLCH) --- */
:root {
  /* Primary Green Scale */
  --green-50:  oklch(97% 0.02 155);
  --green-100: oklch(93% 0.05 155);
  --green-200: oklch(86% 0.10 155);
  --green-300: oklch(78% 0.15 155);
  --green-400: oklch(68% 0.19 155);
  --green-500: oklch(58% 0.20 155);
  --green-600: oklch(48% 0.18 155);
  --green-700: oklch(38% 0.15 155);
  --green-800: oklch(28% 0.10 155);
  --green-900: oklch(18% 0.06 155);

  /* Dark Forest Scale */
  --forest-50:  oklch(96% 0.02 135);
  --forest-100: oklch(90% 0.04 135);
  --forest-200: oklch(80% 0.06 135);
  --forest-300: oklch(70% 0.08 135);
  --forest-400: oklch(60% 0.09 135);
  --forest-500: oklch(35% 0.08 135);
  --forest-600: oklch(28% 0.07 135);
  --forest-700: oklch(22% 0.06 135);
  --forest-800: oklch(16% 0.04 135);
  --forest-900: oklch(10% 0.02 135);

  /* Warm Cream Scale */
  --cream-50:  oklch(99% 0.01 80);
  --cream-100: oklch(96% 0.03 80);
  --cream-200: oklch(92% 0.06 80);
  --cream-300: oklch(86% 0.10 80);
  --cream-400: oklch(78% 0.14 80);
  --cream-500: oklch(70% 0.16 80);

  /* Coffee Brown Scale */
  --coffee-50:  oklch(96% 0.02 60);
  --coffee-100: oklch(90% 0.04 60);
  --coffee-200: oklch(80% 0.07 60);
  --coffee-300: oklch(68% 0.10 60);
  --coffee-400: oklch(55% 0.12 60);
  --coffee-500: oklch(42% 0.11 60);
  --coffee-600: oklch(32% 0.09 60);
  --coffee-700: oklch(24% 0.07 60);
  --coffee-800: oklch(16% 0.04 60);
  --coffee-900: oklch(10% 0.02 60);

  /* Neutral Scale */
  --neutral-0:  oklch(100% 0 0);
  --neutral-50: oklch(98% 0.01 0);
  --neutral-100: oklch(95% 0.01 0);
  --neutral-200: oklch(88% 0.01 0);
  --neutral-300: oklch(75% 0.01 0);
  --neutral-400: oklch(60% 0.01 0);
  --neutral-500: oklch(48% 0.01 0);
  --neutral-600: oklch(36% 0.01 0);
  --neutral-700: oklch(26% 0.01 0);
  --neutral-800: oklch(16% 0.01 0);
  --neutral-900: oklch(8% 0.01 0);

  /* Semantic Colors */
  --color-primary: var(--green-500);
  --color-primary-hover: var(--green-600);
  --color-primary-light: var(--green-100);
  --color-secondary: var(--forest-500);
  --color-accent: var(--cream-400);
  --color-accent-light: var(--cream-100);
  --color-text: var(--forest-700);
  --color-text-muted: var(--neutral-500);
  --color-text-inverse: var(--neutral-0);
  --color-bg: var(--neutral-0);
  --color-bg-warm: var(--cream-50);
  --color-bg-green: var(--green-50);
  --color-surface: var(--neutral-0);
  --color-border: var(--neutral-200);
  --color-border-strong: var(--neutral-300);

  /* Typography */
  --font-heading: "DM Serif Display", Georgia, serif;
  --font-body: "DM Sans", "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Fluid Type Scale (Major Third, clamped) */
  --text-xs:   clamp(0.75rem, 0.7rem + 0.25vw, 0.875rem);
  --text-sm:   clamp(0.875rem, 0.8rem + 0.35vw, 1rem);
  --text-base: clamp(1rem, 0.9rem + 0.5vw, 1.125rem);
  --text-lg:   clamp(1.125rem, 1rem + 0.6vw, 1.25rem);
  --text-xl:   clamp(1.25rem, 1.1rem + 0.75vw, 1.5rem);
  --text-2xl:  clamp(1.5rem, 1.2rem + 1.5vw, 2rem);
  --text-3xl:  clamp(1.875rem, 1.4rem + 2.4vw, 2.5rem);
  --text-4xl:  clamp(2.25rem, 1.6rem + 3.3vw, 3.5rem);
  --text-5xl:  clamp(3rem, 2rem + 5vw, 5rem);

  /* Spacing Scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Radii */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 oklch(0% 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px oklch(0% 0 0 / 0.07), 0 2px 4px -2px oklch(0% 0 0 / 0.07);
  --shadow-lg: 0 10px 15px -3px oklch(0% 0 0 / 0.08), 0 4px 6px -4px oklch(0% 0 0 / 0.08);
  --shadow-xl: 0 20px 25px -5px oklch(0% 0 0 / 0.08), 0 8px 10px -6px oklch(0% 0 0 / 0.08);
  --shadow-soft: 0 8px 32px oklch(0% 0 0 / 0.08);

  /* Transitions */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 350ms cubic-bezier(0.4, 0, 0.2, 1);

  /* Layout */
  --header-height: 4.5rem;
  --container-max: 1280px;
  --container-padding: var(--space-6);
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* --- Typography --- */
h1, h2, h3, h4 {
  font-family: var(--font-heading);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--color-secondary);
}

h1 { font-size: var(--text-5xl); }
h2 { font-size: var(--text-4xl); }
h3 { font-size: var(--text-3xl); }
h4 { font-size: var(--text-2xl); }
h5 { font-size: var(--text-xl); font-weight: 600; }
h6 { font-size: var(--text-lg); font-weight: 600; }

p {
  line-height: 1.7;
  color: var(--color-text);
}

/* --- Layout Utilities --- */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: var(--container-padding);
}

.section {
  padding-block: var(--space-16);
}

.section-sm {
  padding-block: var(--space-10);
}

/* --- Components --- */

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: var(--text-sm);
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-text-inverse);
  box-shadow: var(--shadow-md);
}
.btn-primary:hover {
  background: var(--color-primary-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

.btn-secondary {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}
.btn-secondary:hover {
  background: var(--color-primary-light);
}

.btn-ghost {
  background: transparent;
  color: var(--color-text);
}
.btn-ghost:hover {
  background: var(--neutral-100);
}

.btn-white {
  background: var(--neutral-0);
  color: var(--color-primary);
  box-shadow: var(--shadow-md);
}
.btn-white:hover {
  background: var(--cream-50);
  transform: translateY(-1px);
}

/* Cards */
.card {
  background: var(--color-surface);
  border-radius: var(--radius-2xl);
  overflow: hidden;
  box-shadow: var(--shadow-soft);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

/* Tags / Pills */
.tag {
  display: inline-flex;
  align-items: center;
  padding: var(--space-1) var(--space-3);
  font-size: var(--text-xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: var(--radius-full);
  background: var(--color-primary-light);
  color: var(--color-primary);
}

/* --- Header --- */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--header-height);
  background: oklch(100% 0 0 / 0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: var(--font-heading);
  font-size: var(--text-xl);
  color: var(--color-secondary);
  font-weight: 400;
}

.logo-icon {
  width: 2rem;
  height: 2rem;
  background: var(--color-primary);
  border-radius: var(--radius-full);
  display: grid;
  place-items: center;
  color: white;
  font-size: 1rem;
}

.nav-primary {
  display: flex;
  gap: var(--space-8);
}

.nav-primary a {
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text);
  letter-spacing: 0.03em;
  text-transform: uppercase;
  position: relative;
  padding-block: var(--space-2);
}

.nav-primary a::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--color-primary);
  transition: width var(--transition-base);
}

.nav-primary a:hover::after,
.nav-primary a.active::after {
  width: 100%;
}

.nav-primary a:hover,
.nav-primary a.active {
  color: var(--color-primary);
}

.nav-account {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.nav-account .btn {
  padding: var(--space-2) var(--space-5);
}

.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-secondary);
  transition: all var(--transition-base);
}

/* --- Footer --- */
.footer {
  background: var(--forest-800);
  color: var(--cream-100);
  padding-block: var(--space-16) var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-8);
  margin-bottom: var(--space-12);
}

.footer-col h4 {
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--cream-200);
  margin-bottom: var(--space-4);
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.footer-col a {
  font-size: var(--text-sm);
  color: var(--cream-100);
  opacity: 0.8;
  transition: opacity var(--transition-fast);
}

.footer-col a:hover {
  opacity: 1;
  color: var(--cream-300);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-8);
  border-top: 1px solid oklch(100% 0 0 / 0.1);
}

.footer-bottom p {
  font-size: var(--text-sm);
  color: var(--cream-100);
  opacity: 0.6;
}

.footer-social {
  display: flex;
  gap: var(--space-4);
}

.footer-social a {
  width: 2.5rem;
  height: 2.5rem;
  border-radius: var(--radius-full);
  background: oklch(100% 0 0 / 0.08);
  display: grid;
  place-items: center;
  transition: background var(--transition-fast);
}

.footer-social a:hover {
  background: oklch(100% 0 0 / 0.15);
}

/* Footer Accordion (mobile) */
.footer-accordion-toggle {
  display: none;
  width: 100%;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-3) 0;
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--cream-200);
  border-bottom: 1px solid oklch(100% 0 0 / 0.1);
}

.footer-accordion-toggle::after {
  content: "+";
  font-size: var(--text-lg);
  transition: transform var(--transition-base);
}

.footer-accordion-toggle[aria-expanded="true"]::after {
  content: "−";
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding: var(--space-4) 0;
  box-shadow: var(--shadow-lg);
  transform: translateY(0);
  transition: transform var(--transition-slow);
}

.cookie-banner.hidden {
  transform: translateY(100%);
}

.cookie-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
  flex-wrap: wrap;
}

.cookie-inner p {
  font-size: var(--text-sm);
  color: var(--color-text-muted);
  flex: 1;
}

.cookie-inner strong {
  color: var(--color-text);
  display: block;
  margin-bottom: var(--space-1);
  font-weight: 600;
}

.cookie-actions {
  display: flex;
  gap: var(--space-3);
  flex-shrink: 0;
}

/* --- Hero --- */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--green-50) 0%, var(--cream-100) 50%, var(--green-100) 100%);
  overflow: hidden;
}

.hero::before {
  content: "";
  position: absolute;
  top: -20%;
  right: -10%;
  width: 60%;
  height: 140%;
  background: radial-gradient(ellipse at center, var(--green-200) 0%, transparent 70%);
  opacity: 0.4;
  pointer-events: none;
}

.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
}

.hero-content {
  max-width: 560px;
}

.hero-content h1 {
  margin-bottom: var(--space-6);
  line-height: 1.05;
}

.hero-content p {
  font-size: var(--text-lg);
  color: var(--color-text-muted);
  margin-bottom: var(--space-8);
}

.hero-visual {
  position: relative;
  display: grid;
  place-items: center;
}

.hero-visual .placeholder-img {
  width: 100%;
  aspect-ratio: 4/3;
  border-radius: var(--radius-2xl);
  background: linear-gradient(145deg, var(--green-200), var(--cream-300));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-4xl);
  box-shadow: var(--shadow-xl);
}

/* --- Promo Cards --- */
.promo-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
}

.promo-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-8);
  align-items: center;
  padding: var(--space-8);
  background: var(--color-surface);
  border-radius: var(--radius-2xl);
  box-shadow: var(--shadow-soft);
  overflow: hidden;
}

.promo-card.reverse {
  direction: rtl;
}

.promo-card.reverse > * {
  direction: ltr;
}

.promo-card .placeholder-img {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--radius-xl);
  background: linear-gradient(145deg, var(--green-200), var(--cream-300));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-3xl);
}

.promo-card h3 {
  font-size: var(--text-2xl);
  margin-bottom: var(--space-3);
}

.promo-card p {
  font-size: var(--text-base);
  color: var(--color-text-muted);
  margin-bottom: var(--space-5);
}

/* --- Seasonal Section --- */
.seasonal-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
}

.seasonal-card {
  position: relative;
  padding: var(--space-10);
  border-radius: var(--radius-2xl);
  overflow: hidden;
  min-height: 320px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.seasonal-card.bg-green {
  background: linear-gradient(160deg, var(--green-100) 0%, var(--green-200) 100%);
}

.seasonal-card.bg-cream {
  background: linear-gradient(160deg, var(--cream-100) 0%, var(--cream-200) 100%);
}

.seasonal-card h3 {
  font-size: var(--text-2xl);
  margin-bottom: var(--space-2);
}

.seasonal-card p {
  font-size: var(--text-base);
  margin-bottom: var(--space-5);
  max-width: 380px;
}

/* --- Rewards --- */
.rewards-hero {
  background: linear-gradient(135deg, var(--green-50) 0%, var(--cream-50) 100%);
  padding-block: var(--space-20);
  text-align: center;
}

.rewards-hero h1 {
  margin-bottom: var(--space-4);
}

.rewards-hero p {
  font-size: var(--text-lg);
  color: var(--color-text-muted);
  max-width: 600px;
  margin-inline: auto;
  margin-bottom: var(--space-8);
}

/* How It Works */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.step-card {
  text-align: center;
  padding: var(--space-8);
}

.step-number {
  width: 3.5rem;
  height: 3.5rem;
  border-radius: var(--radius-full);
  background: var(--color-primary);
  color: white;
  font-family: var(--font-heading);
  font-size: var(--text-xl);
  display: grid;
  place-items: center;
  margin-inline: auto;
  margin-bottom: var(--space-5);
}

.step-card h4 {
  font-family: var(--font-body);
  font-size: var(--text-lg);
  font-weight: 700;
  margin-bottom: var(--space-2);
}

/* Tier Cards */
.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.tier-card {
  padding: var(--space-8);
  border-radius: var(--radius-2xl);
  background: var(--color-surface);
  box-shadow: var(--shadow-soft);
  border: 2px solid var(--color-border);
  transition: all var(--transition-base);
}

.tier-card:hover {
  border-color: var(--green-300);
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.tier-card.featured {
  border-color: var(--color-primary);
  background: var(--green-50);
}

.tier-header {
  text-align: center;
  margin-bottom: var(--space-6);
  padding-bottom: var(--space-6);
  border-bottom: 1px solid var(--color-border);
}

.tier-header h3 {
  font-size: var(--text-xl);
  margin-bottom: var(--space-1);
}

.tier-header .stars {
  font-size: var(--text-sm);
  color: var(--color-text-muted);
}

.tier-benefits {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.tier-benefits li {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  font-size: var(--text-sm);
}

.tier-benefits li::before {
  content: "✓";
  color: var(--color-primary);
  font-weight: 700;
  flex-shrink: 0;
}

/* Redemption Tabs */
.redemption-tabs {
  display: flex;
  gap: var(--space-2);
  margin-bottom: var(--space-8);
  flex-wrap: wrap;
  justify-content: center;
}

.redemption-tab {
  padding: var(--space-3) var(--space-5);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text-muted);
  background: var(--neutral-100);
  transition: all var(--transition-base);
  white-space: nowrap;
}

.redemption-tab:hover {
  background: var(--green-100);
  color: var(--color-primary);
}

.redemption-tab.active {
  background: var(--color-primary);
  color: white;
  box-shadow: var(--shadow-md);
}

.redemption-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.redemption-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.redemption-content {
  max-width: 640px;
  margin-inline: auto;
  text-align: center;
